base:
/* ============================================================================
 * waki-themes / base.css
 * ----------------------------------------------------------------------------
 * Shared fundamentals every theme inherits: typography reset, font stack,
 * the .dark / .light class contract for dark-mode toggling, and a small set
 * of utility classes that the demo HTML uses regardless of which theme is
 * active. Each theme file (flat.css / glass-v1.css / glass-v2.css) layers
 * on top — they only override what's visually distinct.
 * ============================================================================ */

@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap");

*,
*::before,
*::after {
  box-sizing: border-box;
}

html, body {
  height: 100%;
}

body {
  margin: 0;
  font-family: "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

html { color-scheme: light; }
html.dark { color-scheme: dark; }

/* Theme switcher pill — sits floating top-right, semi-transparent so it
   reads on any theme. Picked-state button uses a vivid sky tint so the
   active theme is unmistakable. */
.switcher {
  position: fixed;
  top: 0.75rem;
  right: 0.75rem;
  z-index: 60;
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.25rem;
  padding: 0.3rem 0.4rem;
  border-radius: 1.25rem;
  font-size: 0.75rem;
  font-weight: 500;
  user-select: none;
  /* Cap the width so 18 theme buttons wrap to 2-3 rows instead of
     extending across the whole viewport. The pill stays anchored
     top-right and grows downward. */
  max-width: min(540px, calc(100vw - 1.5rem));
}
.switcher button {
  appearance: none;
  border: 0;
  background: transparent;
  color: inherit;
  padding: 0.3rem 0.7rem;
  border-radius: 9999px;
  cursor: pointer;
  font-size: inherit;
  font-family: inherit;
  font-weight: 600;
  transition: background-color 150ms ease-out;
}
.switcher button:hover { background-color: rgba(0, 0, 0, 0.05); }
html.dark .switcher button:hover { background-color: rgba(255, 255, 255, 0.08); }
.switcher button.active {
  background: linear-gradient(135deg, #6366f1, #ec4899);
  color: white;
  box-shadow: 0 4px 12px rgba(99, 102, 241, 0.4);
}
.switcher .divider {
  width: 1px;
  height: 1.1rem;
  background-color: currentColor;
  opacity: 0.25;
  margin: 0 0.25rem;
}

/* Optional shell/demo primitives. Individual themes can override these;
   base keeps new shell samples readable when an older theme is selected. */
.panel-nested {
  background: rgba(255, 255, 255, 0.42);
  border: 1px solid rgba(15, 23, 42, 0.1);
  border-radius: 0.875rem;
}
html.dark .panel-nested {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.12);
}
.theme-swatch {
  background: linear-gradient(135deg, #6366f1, #06b6d4, #ec4899);
}
.theme-switcher {
  background: rgba(255, 255, 255, 0.7);
  border: 1px solid rgba(15, 23, 42, 0.1);
}
html.dark .theme-switcher {
  background: rgba(15, 23, 42, 0.74);
  border-color: rgba(255, 255, 255, 0.12);
}
.nav-item {
  color: inherit;
}

glass-v2.css:
/* ============================================================================
 * waki-themes / glass-v2.css
 * ----------------------------------------------------------------------------
 * Glass theme v2 — everything from v1 plus four layers of polish:
 *   1. SVG fractal-noise texture overlay on the page bg, so the
 *      backdrop-filter has real grain to refract.
 *   2. ::after light glint on each glass card — top-left fade
 *      gradient that reads like a light source catching the surface.
 *   3. Hover treatment that brightens the card slightly with a
 *      smooth 200ms transition, like glass catching light when you
 *      look straight on.
 *   4. Slow `gradientShift` animation on the body bg-position so the
 *      gradient drifts under the glass surfaces. 30s cycle — barely
 *      perceptible but enough to keep the surfaces from feeling
 *      static. Disabled under prefers-reduced-motion.
 * ============================================================================ */

/* ----- Page background + drift animation ------------------------------- */
body {
  background: linear-gradient(135deg, #e8eef5 0%, #f0f4f9 30%, #e5edf6 60%, #eef2f8 100%);
  background-attachment: fixed;
  background-size: 200% 200%;
  animation: gradientShift 30s ease-in-out infinite;
  color: #0f172a;
}
html.dark body {
  background: linear-gradient(135deg, #0c1220 0%, #162033 30%, #1a2744 60%, #0f1a2e 100%);
  background-attachment: fixed;
  background-size: 200% 200%;
  animation: gradientShift 30s ease-in-out infinite;
  color: #f1f5f9;
}

@keyframes gradientShift {
  0%   { background-position: 0% 0%; }
  50%  { background-position: 100% 100%; }
  100% { background-position: 0% 0%; }
}

/* SVG fractal-noise grain overlay. Inlined as a data URI so this CSS
   file is fully self-contained — drop it in any project, no asset
   pipeline needed. */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  opacity: 0.03;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 256px 256px;
  pointer-events: none;
}
html.dark body::before {
  opacity: 0.04;
}

/* ----- Surfaces --------------------------------------------------------- */
/* `position: relative` here so the absolute ::after glint positions
   against the card itself, not some distant ancestor. */
.glass {
  position: relative;
  background: rgba(255, 255, 255, 0.65);
  backdrop-filter: blur(12px) saturate(150%);
  -webkit-backdrop-filter: blur(12px) saturate(150%);
  border: 1px solid rgba(255, 255, 255, 0.5);
  border-radius: 0.875rem;
  box-shadow: 0 8px 32px rgba(15, 23, 42, 0.08);
  transition: background-color 200ms ease-out, box-shadow 200ms ease-out;
}
html.dark .glass {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.1);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25);
}

.glass-elevated {
  position: relative;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(16px) saturate(180%);
  -webkit-backdrop-filter: blur(16px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-radius: 0.875rem;
  box-shadow: 0 12px 40px rgba(15, 23, 42, 0.1);
  transition: background-color 200ms ease-out, box-shadow 200ms ease-out;
}
html.dark .glass-elevated {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.15);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.3);
}

/* Light glint — top-left highlight that traces the card outline.
   border-radius: inherit makes it follow whatever radius the host
   card has, so the same rule works on a pill / rounded-xl / square
   card without per-element overrides. pointer-events: none so it
   never catches taps. */
.glass::after,
.glass-elevated::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.18) 0%, transparent 50%);
  pointer-events: none;
}
html.dark .glass::after,
html.dark .glass-elevated::after {
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.1) 0%, transparent 50%);
}

/* Hover — slightly more opaque + deeper drop shadow, like real glass
   brightening when you look at it straight on. */
.glass:hover {
  background: rgba(255, 255, 255, 0.75);
  box-shadow: 0 12px 40px rgba(15, 23, 42, 0.12);
}
html.dark .glass:hover {
  background: rgba(255, 255, 255, 0.1);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.35);
}
.glass-elevated:hover {
  background: rgba(255, 255, 255, 0.88);
  box-shadow: 0 16px 48px rgba(15, 23, 42, 0.14);
}
html.dark .glass-elevated:hover {
  background: rgba(255, 255, 255, 0.14);
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.4);
}

.glass-bar {
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(18px) saturate(160%);
  -webkit-backdrop-filter: blur(18px) saturate(160%);
}
html.dark .glass-bar {
  background: rgba(15, 23, 42, 0.55);
}

.chip {
  background: rgba(255, 255, 255, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.5);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
html.dark .chip {
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.1);
}

.divider-soft {
  border-color: rgba(15, 23, 42, 0.08);
}
html.dark .divider-soft {
  border-color: rgba(255, 255, 255, 0.08);
}

/* Honour user motion preferences. The drifting page gradient is the
   exact kind of background motion that triggers vestibular discomfort
   for some users. */

/* ----- Action buttons --------------------------------------------------- */
/* Required by SCHEMA.md (v0.4.0). Theme CSS loads after waki-shell
 * utilities.css so equal-specificity rules win without !important. */
.btn-primary {
  background: linear-gradient(135deg, #6366f1 0%, #4f46e5 100%);
  color: #ffffff;
  border: 1px solid #4f46e580;
  box-shadow: 0 4px 14px #6366f150;
}
.btn-primary:hover {
  background: linear-gradient(135deg, #4f46e5 0%, #4f46e5 100%);
}
html.dark .btn-primary {
  background: linear-gradient(135deg, #818cf8 0%, #6366f1 100%);
  color: #0a0e1a;
  box-shadow: 0 4px 14px #818cf855;
}
html.dark .btn-primary:hover {
  background: linear-gradient(135deg, #6366f1 0%, #6366f1 100%);
}

.btn-secondary {
  background: rgba(255, 255, 255, 0.78);
  color: #0f172a;
  border: 1px solid rgba(15, 23, 42, 0.1);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.08);
}
.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.78);
  filter: brightness(1.05);
  border-color: rgba(15, 23, 42, 0.1);
}
html.dark .btn-secondary {
  background: rgba(255, 255, 255, 0.08);
  color: #f1f5f9;
  border-color: rgba(255, 255, 255, 0.14);
}
html.dark .btn-secondary:hover {
  background: rgba(255, 255, 255, 0.08);
  filter: brightness(1.15);
}

.btn-warning {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  color: #ffffff;
  border: 1px solid rgba(217, 119, 6, 0.5);
  box-shadow: 0 4px 14px rgba(217, 119, 6, 0.3);
}
.btn-warning:hover {
  background: linear-gradient(135deg, #d97706 0%, #b45309 100%);
}
html.dark .btn-warning {
  background: linear-gradient(135deg, #fbbf24 0%, #f59e0b 100%);
  color: #1a0f00;
  box-shadow: 0 4px 14px rgba(251, 191, 36, 0.35);
}
html.dark .btn-warning:hover {
  background: linear-gradient(135deg, #fcd34d 0%, #fbbf24 100%);
}

.btn-danger {
  background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
  color: #ffffff;
  border: 1px solid rgba(220, 38, 38, 0.5);
  box-shadow: 0 4px 14px rgba(220, 38, 38, 0.3);
}
.btn-danger:hover {
  background: linear-gradient(135deg, #dc2626 0%, #b91c1c 100%);
}
html.dark .btn-danger {
  background: linear-gradient(135deg, #f87171 0%, #ef4444 100%);
  color: #1a0000;
  box-shadow: 0 4px 14px rgba(248, 113, 113, 0.35);
}
html.dark .btn-danger:hover {
  background: linear-gradient(135deg, #fca5a5 0%, #f87171 100%);
}

.btn-ghost {
  background: transparent;
  color: #0f172a;
  border: 1px solid transparent;
}
.btn-ghost:hover {
  background: rgba(99, 102, 241, 0.08);
  border-color: rgba(99, 102, 241, 0.2);
}
html.dark .btn-ghost {
  color: #f1f5f9;
}
html.dark .btn-ghost:hover {
  background: rgba(99, 102, 241, 0.14);
  border-color: rgba(99, 102, 241, 0.26);
}


/* ----- Status + success + input (SCHEMA.md recommended) ---------------- */
.btn-success {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  color: #ffffff;
  border: 1px solid rgba(5, 150, 105, 0.55);
  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.3);
}
.btn-success:hover {
  background: linear-gradient(135deg, #059669 0%, #047857 100%);
}
html.dark .btn-success {
  background: linear-gradient(135deg, #34d399 0%, #10b981 100%);
  color: #022c22;
  box-shadow: 0 4px 14px rgba(52, 211, 153, 0.35);
}

.status-success {
  background: rgba(16, 185, 129, 0.12);
  color: #047857;
  border: 1px solid rgba(16, 185, 129, 0.32);
}
html.dark .status-success {
  background: rgba(52, 211, 153, 0.16);
  color: #6ee7b7;
  border-color: rgba(52, 211, 153, 0.36);
}

.status-warning {
  background: rgba(245, 158, 11, 0.12);
  color: #b45309;
  border: 1px solid rgba(245, 158, 11, 0.32);
}
html.dark .status-warning {
  background: rgba(251, 191, 36, 0.16);
  color: #fcd34d;
  border-color: rgba(251, 191, 36, 0.36);
}

.status-error {
  background: rgba(239, 68, 68, 0.12);
  color: #b91c1c;
  border: 1px solid rgba(239, 68, 68, 0.32);
}
html.dark .status-error {
  background: rgba(248, 113, 113, 0.16);
  color: #fca5a5;
  border-color: rgba(248, 113, 113, 0.36);
}

.status-info {
  background: rgba(59, 130, 246, 0.12);
  color: #1d4ed8;
  border: 1px solid rgba(59, 130, 246, 0.32);
}
html.dark .status-info {
  background: rgba(96, 165, 250, 0.16);
  color: #93c5fd;
  border-color: rgba(96, 165, 250, 0.36);
}

.input {
  background: rgba(255, 255, 255, 0.78);
  color: #0f172a;
  border: 1px solid rgba(15, 23, 42, 0.1);
  border-radius: 8px;
  padding: 0.5rem 0.75rem;
  outline: none;
  transition: border-color 150ms ease-out, box-shadow 150ms ease-out;
}
.input:focus {
  border-color: #6366f1;
  box-shadow: 0 0 0 3px #6366f125;
}
html.dark .input {
  background: rgba(255, 255, 255, 0.08);
  color: #f1f5f9;
  border-color: rgba(255, 255, 255, 0.14);
}
html.dark .input:focus {
  border-color: #818cf8;
  box-shadow: 0 0 0 3px #818cf830;
}

@media (prefers-reduced-motion: reduce) {
  body {
    animation: none !important;
  }
}

glass-plus.css:
/* ============================================================================
 * waki-themes / glass-plus.css
 * ----------------------------------------------------------------------------
 * Glass with the dial turned up. Same architecture as glass-v2 (frosted
 * surfaces, fractal-noise grain, ::after light glint, drifting page
 * gradient) but with the saturation and chroma pushed in three places:
 *
 *   1. Page bg gradient gets a violet/sky tilt instead of cool slate.
 *      Same brightness floor; the difference is hue, not luminosity.
 *   2. Card surface tint takes a faint violet wash instead of plain
 *      neutral white-on-dark / white-on-light, so the brand's palette
 *      reads through every panel.
 *   3. Panels gain a touch more contrast against the bg (slightly
 *      higher opacity in light mode, slightly higher opacity + more
 *      saturated tint in dark) so the layered cards feel less wispy
 *      than vanilla Glass.
 *
 * This is the new default. Glass-v2 stays as the calmer alternative
 * for users who want the same mechanic with less brand wash.
 * ============================================================================ */

/* ----- Page background + drift animation ------------------------------- */
body {
  /* Light mode: warm-cool wash with a touch of violet. */
  background: linear-gradient(135deg, #eef0fb 0%, #f3eaf8 30%, #e7eef9 60%, #f0eaf6 100%);
  background-attachment: fixed;
  background-size: 220% 220%;
  animation: gradientShift 30s ease-in-out infinite;
  color: #0f172a;
}
html.dark body {
  /* Dark: violet/sky undertone. Distinct from glass-v2's cool-blue. */
  background: linear-gradient(135deg, #100b24 0%, #1a1640 30%, #131a3a 60%, #0d0a22 100%);
  background-attachment: fixed;
  background-size: 220% 220%;
  animation: gradientShift 30s ease-in-out infinite;
  color: #f1f5f9;
}

@keyframes gradientShift {
  0%   { background-position: 0% 0%; }
  50%  { background-position: 100% 100%; }
  100% { background-position: 0% 0%; }
}

/* SVG fractal-noise grain overlay. Inlined so this CSS file is
   self-contained. */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  opacity: 0.04;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 256px 256px;
  pointer-events: none;
}
html.dark body::before {
  opacity: 0.06;
}

/* ----- Surfaces --------------------------------------------------------- */
.glass {
  position: relative;
  /* Higher opacity than vanilla Glass + a faint violet wash. */
  background: rgba(243, 235, 255, 0.72);
  backdrop-filter: blur(14px) saturate(180%);
  -webkit-backdrop-filter: blur(14px) saturate(180%);
  border: 1px solid rgba(168, 85, 247, 0.22);
  border-radius: 0.875rem;
  box-shadow: 0 8px 32px rgba(99, 102, 241, 0.1);
  transition: background-color 200ms ease-out, box-shadow 200ms ease-out;
}
html.dark .glass {
  /* More saturated violet tint than vanilla Glass's plain white-on-dark. */
  background: rgba(168, 85, 247, 0.1);
  border-color: rgba(168, 85, 247, 0.26);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
}

.glass-elevated {
  position: relative;
  background: rgba(247, 240, 255, 0.85);
  backdrop-filter: blur(18px) saturate(200%);
  -webkit-backdrop-filter: blur(18px) saturate(200%);
  border: 1px solid rgba(168, 85, 247, 0.32);
  border-radius: 0.875rem;
  box-shadow: 0 12px 40px rgba(99, 102, 241, 0.12);
  transition: background-color 200ms ease-out, box-shadow 200ms ease-out;
}
html.dark .glass-elevated {
  background: rgba(168, 85, 247, 0.16);
  border-color: rgba(168, 85, 247, 0.36);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.36);
}

/* Light glint. Pushed slightly brighter than vanilla Glass so the
   "real glass catching light" feel is more pronounced. */
.glass::after,
.glass-elevated::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.24) 0%, transparent 55%);
  pointer-events: none;
}
html.dark .glass::after,
html.dark .glass-elevated::after {
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.14) 0%, transparent 55%);
}

/* Hover. Same mechanic as vanilla Glass; brighter swing because the
   resting state is already more saturated. */
.glass:hover {
  background: rgba(247, 240, 255, 0.84);
  box-shadow: 0 14px 44px rgba(99, 102, 241, 0.15);
}
html.dark .glass:hover {
  background: rgba(168, 85, 247, 0.16);
  box-shadow: 0 14px 44px rgba(0, 0, 0, 0.4);
}
.glass-elevated:hover {
  background: rgba(247, 240, 255, 0.92);
  box-shadow: 0 18px 56px rgba(99, 102, 241, 0.18);
}
html.dark .glass-elevated:hover {
  background: rgba(168, 85, 247, 0.22);
  box-shadow: 0 18px 56px rgba(0, 0, 0, 0.46);
}

.glass-bar {
  background: rgba(247, 240, 255, 0.78);
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
}
html.dark .glass-bar {
  background: rgba(26, 22, 64, 0.6);
}

.chip {
  background: rgba(168, 85, 247, 0.1);
  border: 1px solid rgba(168, 85, 247, 0.26);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
html.dark .chip {
  background: rgba(168, 85, 247, 0.12);
  border-color: rgba(168, 85, 247, 0.3);
}

.divider-soft {
  border-color: rgba(168, 85, 247, 0.14);
}
html.dark .divider-soft {
  border-color: rgba(168, 85, 247, 0.18);
}

/* ----- Action buttons --------------------------------------------------- */
/* Required by SCHEMA.md. Glass-Plus leans violet on a violet-wash canvas;
 * primary uses the brand gradient, secondary is a frosted violet panel,
 * warning + danger keep amber/red so destructive intent reads at a glance.
 * Theme CSS loads after waki-shell utilities.css so equal-specificity
 * rules win without !important. */
.btn-primary {
  background: linear-gradient(135deg, #a855f7 0%, #7c3aed 100%);
  color: #ffffff;
  border: 1px solid rgba(168, 85, 247, 0.5);
  box-shadow: 0 4px 14px rgba(168, 85, 247, 0.3);
}
.btn-primary:hover {
  background: linear-gradient(135deg, #9333ea 0%, #6d28d9 100%);
}
html.dark .btn-primary {
  background: linear-gradient(135deg, #c084fc 0%, #a855f7 100%);
  color: #1a0d2e;
  box-shadow: 0 4px 14px rgba(192, 132, 252, 0.4);
}
html.dark .btn-primary:hover {
  background: linear-gradient(135deg, #d8b4fe 0%, #c084fc 100%);
}

.btn-secondary {
  background: rgba(243, 235, 255, 0.78);
  color: #0f172a;
  border: 1px solid rgba(168, 85, 247, 0.32);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 2px 8px rgba(99, 102, 241, 0.1);
}
.btn-secondary:hover {
  background: rgba(243, 235, 255, 0.92);
  border-color: rgba(168, 85, 247, 0.45);
}
html.dark .btn-secondary {
  background: rgba(168, 85, 247, 0.16);
  color: #f1f5f9;
  border-color: rgba(168, 85, 247, 0.32);
}
html.dark .btn-secondary:hover {
  background: rgba(168, 85, 247, 0.24);
  border-color: rgba(168, 85, 247, 0.45);
}

.btn-warning {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  color: #ffffff;
  border: 1px solid rgba(217, 119, 6, 0.5);
